css.stylesheet:
html {
	--mobile-scale: 1.4;
	--mobile-padding-offset: 0.6;
}

body {
	--swatch-1: rgba(255, 255, 255, 0.85);
	--swatch-2: rgba(255, 255, 255, 0.75);
	--swatch-3: rgba(255, 255, 255, 0.6);
	--swatch-4: rgba(255, 255, 255, 0.4);
	--swatch-5: rgba(255, 255, 255, 0.25);
	background-color: #ffffff;
}

body.mobile {
}

a:active,
.linked:active,
.zoomable::part(media):active {
	opacity: 0.7;
}

.page a.active {

}

sub {
	position: relative;
	vertical-align: baseline;
	top: 0.3em;
}

sup {
	position: relative;
	vertical-align: baseline;
	top: -0.4em;
}

.small-caps {
	font-variant: small-caps;
    text-transform: lowercase;
}

ol {
	margin: 0;
	padding: 0 0 0 2.5em;
}

ul {
	margin: 0;
	padding: 0 0 0 2.0em;
}

ul.lineated {
	margin: 0;
	padding: 0;
	list-style-type: none;
	margin: 0 0 0 3em;
	text-indent: -3em;
}

blockquote {
	margin: 0;
	padding: 0 0 0 2em;
}

hr {
	background: rgba(255, 255, 255, 0.25);
	border: 0;
	height: 1px;
	display: block;
	margin-top: 0.8rem;
	margin-bottom: 1rem;
}

.content {
	border-color: rgba(0,0,0,.85);
}

bodycopy {
	font-size: 1rem;
	font-weight: normal;
	color: rgba(0, 0, 0, 0.88);
	font-family: HelveticaNeue-Light, Helvetica Neue Light;
	font-style: normal;
	line-height: 1.2;
	letter-spacing: 0;
	display: block;
}

bodycopy a {
	color: rgba(0, 0, 0, 0.88);
	text-decoration: none;
}

bodycopy a:hover {
}

h1 {
	font-family: HelveticaNeue-Light, Helvetica Neue Light;
	font-style: normal;
	font-weight: normal;
	margin: 0;
	font-size: 3.8rem;
	line-height: 1.1;
	color: #000000;
	letter-spacing: 0;
}

h1 a {
	color: #000000;
	text-decoration: none;
}

h1 a:hover {
}

h2 {
	font-family: HelveticaNeue-Light, Helvetica Neue Light;
	font-style: normal;
	font-weight: normal;
	margin: 0;
	color: #000000;
	font-size: 2rem;
	line-height: 1.3;
	letter-spacing: 0;
}

h2 a {
	color: #000000;
	text-decoration: none;
}

h2 a:hover {
}

.caption {
	font-size: 1rem;
	font-weight: normal;
	color: #000000;
	font-family: HelveticaNeue-Light, Helvetica Neue Light;
	font-style: normal;
	line-height: 1.1;
	letter-spacing: 0;
	display: block;
}

.caption a {
	color: #000000;
	text-decoration: none;
}

.caption a:hover {
}

media-item .caption {
	margin-top: 0.7em;
}

gallery-slideshow .caption {
	margin-top: 1em;
}

gallery-grid .caption,
gallery-columnized .caption,
gallery-justify .caption {
	margin-bottom: 3em;
}

[thumbnail-index] .caption {
	text-align: center;
}

[thumbnail-index] .caption .tags {
	margin-top: 0.25em;
}

.page {
	justify-content: center;
}

.page-content {
	padding: 1rem;
	text-align: left;
}

.mobile [id] .page-layout {
	max-width: 100%;
}

.page-layout {
	align-items: flex-start;
	max-width: 100%;
}

media-item::part(media) {
	border: 0;
}

.quick-view {
	height: 100%;
	width: 100%;
	padding: 4.0rem;
	margin-top: auto;
	margin-right: auto;
	margin-bottom: auto;
	margin-left: auto;
}

.quick-view-background {
	background-color: #191919;
}

.quick-view .caption {
	color: #000000;
	padding: 20px 0;
	text-align: center;
	transition: 100ms opacity ease-in-out;
	position: absolute;
	bottom: 0;
	left: 0;
	right: 0;
}

.quick-view .caption-background {
	padding: 0.5rem 1rem;
	display: inline-block;
	background: rgba(255, 255, 255, 0.85);
	border-radius: .5rem;
	text-align: left;
	max-width: 50rem;
}

.mobile .quick-view {
	width: 100%;
	height: 100%;
	margin: 0;
	padding: 10px;
}

.mobile .quick-view .caption {
	padding: 10px 0;
}

.mobile .quick-view .caption-background {
	max-width: 100vw;
}

::part(slideshow-nav) {
	--button-size: 30px;
	--button-inset: 20px;
	--button-icon-color: rgba(0, 0, 0, 0.9);
	--button-icon-stroke-width: 1.5px;
	--button-icon-stroke-linecap: none;
	--button-background-color: rgba(168, 168, 168, 0.6);
	--button-background-radius: 50%;
	--button-active-opacity: 0.7;
}

gallery-slideshow::part(slideshow-nav) {
	--button-inset: 15px;
}

.quick-view::part(slideshow-nav) {
}

.wallpaper-slideshow::part(slideshow-nav) {
}

.mobile ::part(slideshow-nav) {
	--button-inset: 10px;
}

.mobile .quick-view::part(slideshow-nav) {
	--button-inset: 25px;
}

shop-product {
	font-size: 1.2rem;
	max-width: 22rem;
	font-family: "Diatype Variable";
	font-style: normal;
	font-weight: 400;
	font-variation-settings: 'slnt' 0, 'MONO' 0;
	letter-spacing: 0em;
	margin-bottom: 1em;
}

shop-product::part(price) {
	color: rgba(255, 255, 255, 0.85);
	line-height: 1.1;
	margin-bottom: 0.5em;
}

shop-product::part(dropdown) {
	width: 100%;
	color: rgba(255, 255, 255, 0.85);
	border: 1px solid rgba(255, 255, 255, 0.27);
	background-color: rgba(0, 0, 0, 0.0);
	background-image: url(https://static.cargo.site/assets/images/select-line-arrows-light.svg);
	background-repeat: no-repeat;
	background-position: top 0em right .1em;
	line-height: 1.2;
	padding: 0.58em 2em 0.55em 0.9em;
	border-radius: 10em;
	margin-bottom: 0.5em;
}

shop-product::part(button) {
	background: rgba(255, 255, 255, 0.2);
	color: rgba(255, 255, 255, 0.85);
	text-align: left;
	line-height: normal;
	padding: 0.5em 1em;
	cursor: pointer;
	border-radius: 10em;
}

shop-product::part(button):active {
	opacity: .7;
}

audio-player {
	--text-color: rgba(255, 255, 255, 0.85);
	--text-padding: 0 1.2em 0 1.0em;
	--background-color: rgba(255, 255, 255, 0);
	--buffer-background-color: rgba(255, 255, 255, 0.075);
	--progress-background-color: rgba(255, 255, 255, 0.12);
	--border-lines: 1px solid rgba(255, 255, 255, 0.25);
	font-size: 1.2rem;
	width: 32rem;
	height: 2.75em;
	font-family: "Diatype Variable";
	font-style: normal;
	font-weight: 400;
	font-variation-settings: 'slnt' 0, 'MONO' 0;
	line-height: normal;
	letter-spacing: 0em;
	margin-bottom: 0.5em;
	border-radius: 10em;
}

audio-player::part(button) {
	--icon-color: rgba(255, 255, 255, 0.85);
	--icon-size: 32%;
	--play-text: '';
	--pause-text: '';
	width: 3.15em;
	display: inline-flex;
	justify-content: center;
	cursor: pointer;
}

audio-player::part(play-icon) {
	padding-left: 0.6em;
}

audio-player::part(pause-icon) {
	padding-left: 0.4em;
}

audio-player::part(progress-indicator) {
	border-right: 1px solid rgba(255, 255, 255, 0);
	height: 100%;
	cursor: ew-resize;
}

audio-player::part(separator) {
	border-right: var(--border-lines);
}

body.mobile audio-player {
	max-width: 100%;
}

media-item {
	--scroll-animation-mode: animation;
	--scroll-animation: scrollAnimationFlyIn-2;
	--scroll-animation-timing: cubic-bezier(0.39, 0.575, 0.565, 1);
}

@keyframes scrollAnimationFlyIn-2 { 
	0% { transform: translateY(10vh); }
	30% { transform: scale(1); }
	70% { transform: scale(1); }
	100% { transform: scale(1); }
}
